    // Tempo de execução: 167558200 nanosegundos
    public List<Integer> sortV1(List<Integer> list) {
        long startTime = System.nanoTime();
        List<Integer> orderedList = new ArrayList<>();
        for (int i = 1; i < list.size(); i++) {
            maiorNumeroDaIteracao = -99999;
            list.forEach(inteiro -> {
                if (inteiro > maiorNumeroDaIteracao && !orderedList.contains(inteiro)) {
                    maiorNumeroDaIteracao = inteiro;
                }
            });
            orderedList.add(maiorNumeroDaIteracao);
        }
        long endTime = System.nanoTime();
        long duration = endTime - startTime;
        System.out.println("Tempo de execução: " + duration + " nanosegundos");
        return orderedList;
    }

    // Tempo de execução: 18138300 nanosegundos
    public List<Integer> sortV2(List<Integer> list) {
        List<Integer> newList = new ArrayList<Integer>(list);
        long startTime = System.nanoTime();
        List<Integer> orderedList = new ArrayList<>();
        for (int i = 1; i < list.size(); i++) {
            maiorNumeroDaIteracao = -99999;
            newList.forEach(inteiro -> {
                if (inteiro > maiorNumeroDaIteracao) {
                    maiorNumeroDaIteracao = inteiro;
                }
            });
            newList.remove(maiorNumeroDaIteracao);
            orderedList.add(maiorNumeroDaIteracao);
        }
        long endTime = System.nanoTime();
        long duration = endTime - startTime;
        System.out.println("Tempo de execução: " + duration + " nanosegundos");
        return orderedList;
    }

